1	package warranty
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件回归保障“保修请求先提交、产品资料后登记”：SubmitRequest 允许
10	// 关联尚未登记的产品，产品缺失留待资格查询与预留时报告（ErrNotFound）；
11	// 失败不产生承诺、不占用库存，并在该请求的预留历史中留下资格依据与库存
12	// 依据均为空的产品缺失记录。随后补登产品资料即作用于原请求——无需再次
13	// 提交或替换请求——资格按补登条款正常判断，沿用此前失败的承诺编号与
14	// 预留内容重试即可成功；早先的缺失记录不被补登资料回填、不被成功记录
15	// 覆盖，两条记录各有自己的递增序号。若补登条款把原请求的故障代码列为
16	// 除外，资格明确显示除外原因、预留返回 ErrIneligible，本次失败历史保存
17	// 已取得的资格与库存依据，而原请求的产品编号、故障代码及此前缺失记录
18	// 仍然保留。测试只沿用既有公开入口与现有错误类别，不改变任何规则。
19	
20	// 本文件专用编号，避免与其他测试文件混用。
21	const (
22		lpProductID   = "p-late"
23		lpOtherProdID = "p-late-other"
24		lpPartID      = "part-late"
25		lpReqID       = "r-late"
26		lpOtherReqID  = "r-late-other"
27		lpCommitID    = "c-late"
28		lpOtherCommit = "c-late-other"
29		lpFaultCode   = "NOISE"
30	)
31	
32	// lpClock 汇集主例的全部时刻。
33	type lpClock struct {
34		purchase  time.Time // 补登产品的购买时刻
35		deadline  time.Time // 保修截止时刻：购买时刻起第三十天
36		firstAt   time.Time // 产品缺失期间资格查询与首次预留的当次当前时刻
37		firstExp  time.Time // 首次预留的到期时刻，晚于 firstAt
38		secondAt  time.Time // 补登后再次判断与重试预留的当次当前时刻
39		secondExp time.Time // 重试预留的到期时刻，晚于 secondAt
40	}
41	
42	// lpBaseScenario 构造用户给出的主例：备件 part-late 有 10 件实物；另一张
43	// 关联已登记产品的合格请求 r-late-other 已有效占用 4 件。新请求 r-late
44	// 关联尚未登记的产品 p-late，故障代码 NOISE 非空。此刻 p-late 尚未登记。
45	func lpBaseScenario(t *testing.T) (*Store, lpClock) {
46		t.Helper()
47		clk := lpClock{
48			purchase:  t0,
49			deadline:  t0.Add(30 * day),
50			firstAt:   t0.Add(10 * day),
51			firstExp:  t0.Add(45 * day),
52			secondAt:  t0.Add(11 * day),
53			secondExp: t0.Add(46 * day),
54		}
55	
56		s := NewStore()
57		// 另一张合格请求依赖的已登记产品（条款不除外 NOISE）。
58		if err := s.RegisterProduct(lpOtherProdID, t0, 365, nil); err != nil {
59			t.Fatalf("register other product: %v", err)
60		}
61		if err := s.RegisterPart(lpPartID, 10); err != nil {
62			t.Fatalf("register part: %v", err)
63		}
64		// 另一张合格请求，并有效占用 4 件。
65		if err := s.SubmitRequest(lpOtherReqID, lpOtherProdID, "OTHER_FAULT"); err != nil {
66			t.Fatalf("submit other request: %v", err)
67		}
68		if _, err := s.Reserve(lpOtherCommit, lpOtherReqID, lpPartID, 4, clk.firstExp, clk.firstAt); err != nil {
69			t.Fatalf("reserve other commitment: %v", err)
70		}
71		// 新请求关联一个尚未登记的产品，故障代码非空：提交本身必须成功。
72		if err := s.SubmitRequest(lpReqID, lpProductID, lpFaultCode); err != nil {
73			t.Fatalf("submit request before product registration: %v", err)
74		}
75		return s, clk
76	}
77	
78	// assertStock10x6 断言备件账目保持：实物 10 件、有效占用 4 件、可承诺 6 件。
79	func assertStock10x6(t *testing.T, s *Store, now time.Time) {
80		t.Helper()
81		st, err := s.PartStatus(lpPartID, now)
82		if err != nil {
83			t.Fatalf("part status: %v", err)
84		}
85		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 4 || st.Committable != 6 {
86			t.Fatalf("stock = phys %d / occupied %d / committable %d, want 10/4/6",
87				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
88		}
89	}
90	
91	// assertMissingProductFailureRecord 断言产品缺失失败记录的完整内容：保存
92	// 提交编号、备件、数量、到期时刻与当次当前时刻；即使备件已经存在，资格
93	// 依据和库存依据也都为空。
94	func assertMissingProductFailureRecord(t *testing.T, rec HistoryRecord, seq int, clk lpClock) {
95		t.Helper()
96		if rec.Seq != seq {
97			t.Fatalf("seq = %d, want %d", rec.Seq, seq)
98		}
99		if rec.Success {
100			t.Fatalf("missing-product record marked success: %+v", rec)
101		}
102		if rec.Error != HistoryErrorProductNotFound {
103			t.Fatalf("error category = %q, want %q", rec.Error, HistoryErrorProductNotFound)
104		}
105		if rec.CommitID != lpCommitID || rec.PartID != lpPartID || rec.Quantity != 3 {
106			t.Fatalf("submission content = %q/%q/%d, want %q/%q/3",
107				rec.CommitID, rec.PartID, rec.Quantity, lpCommitID, lpPartID)
108		}
109		if !rec.Expiry.Equal(clk.firstExp) || !rec.Now.Equal(clk.firstAt) {
110			t.Fatalf("times = expiry %v now %v, want %v / %v",
111				rec.Expiry, rec.Now, clk.firstExp, clk.firstAt)
112		}
113		// 即使备件已经存在，这条记录的资格依据和库存依据也都为空。
114		if rec.Eligibility != nil {
115			t.Fatalf("missing-product record must have nil eligibility, got %+v", rec.Eligibility)
116		}
117		if rec.StockBasis != nil {
118			t.Fatalf("missing-product record must have nil stock basis even though part exists, got %+v", rec.StockBasis)
119		}
120	}
121	
122	// TestRequestBeforeProduct_MissingPeriod 产品缺失期间：资格查询（Evaluate
123	// 与 RequestView）和预留都返回 ErrNotFound；失败不产生承诺，实物仍 10 件、
124	// 有效占用 4 件、可承诺 6 件；预留历史留下产品缺失的失败记录，保存提交
125	// 编号、备件、数量、到期时刻和当次当前时刻，且资格依据、库存依据均为空。
126	func TestRequestBeforeProduct_MissingPeriod(t *testing.T) {
127		s, clk := lpBaseScenario(t)
128	
129		// 提交时不校验产品：请求确实已保存，且保留原产品编号与故障代码。
130		req, err := s.Request(lpReqID)
131		if err != nil {
132			t.Fatalf("request lookup: %v", err)
133		}
134		if req.ProductID != lpProductID || req.FaultCode != lpFaultCode {
135			t.Fatalf("saved request = %+v, want product %q fault %q", req, lpProductID, lpFaultCode)
136		}
137		// 产品确实尚未登记。
138		if _, err := s.Product(lpProductID); !errors.Is(err, ErrNotFound) {
139			t.Fatalf("product should be missing: got %v", err)
140		}
141	
142		// 资格查询：产品缺失返回 ErrNotFound。
143		if _, err := s.Evaluate(lpReqID, clk.firstAt); !errors.Is(err, ErrNotFound) {
144			t.Fatalf("evaluate while product missing: got %v, want ErrNotFound", err)
145		}
146		// 按请求查看同样沿用现有错误类别报告缺失。
147		if _, err := s.RequestView(lpReqID, clk.firstAt); !errors.Is(err, ErrNotFound) {
148			t.Fatalf("request view while product missing: got %v, want ErrNotFound", err)
149		}
150	
151		// 预留 3 件，到期时刻晚于当次时刻：因产品缺失返回 ErrNotFound。
152		if _, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.firstExp, clk.firstAt); !errors.Is(err, ErrNotFound) {
153			t.Fatalf("reserve while product missing: got %v, want ErrNotFound", err)
154		}
155	
156		// 失败不能产生承诺：编号未被占用，请求下也没有任何承诺明细。
157		if _, err := s.Commitment(lpCommitID); !errors.Is(err, ErrNotFound) {
158			t.Fatalf("failed reserve created a commitment: got %v", err)
159		}
160		if view, err := s.RequestView(lpReqID, clk.firstAt); err == nil {
161			t.Fatalf("request view should still report missing product, got view with %d commitments",
162				len(view.Commitments))
163		}
164	
165		// 实物仍为 10、有效占用仍为 4、可承诺仍为 6（另一张请求的占用不变）。
166		assertStock10x6(t, s, clk.firstAt)
167	
168		// 该请求的预留历史留下产品缺失的失败记录。
169		h, err := s.RequestHistory(lpReqID)
170		if err != nil {
171			t.Fatalf("history: %v", err)
172		}
173		if len(h) != 1 {
174			t.Fatalf("history len = %d, want 1", len(h))
175		}
176		assertMissingProductFailureRecord(t, h[0], 1, clk)
177	
178		// 另一张请求的 4 件占用与它自己的历史均保持原值。
179		other, err := s.RequestHistory(lpOtherReqID)
180		if err != nil {
181			t.Fatalf("other history: %v", err)
182		}
183		if len(other) != 1 || !other[0].Success || other[0].CommitID != lpOtherCommit || other[0].Quantity != 4 {
184			t.Fatalf("other request history altered: %+v", other)
185		}
186	}
187	
188	// TestRequestBeforeProduct_RegisterEligibleThenRetrySucceeds 补登合格条款：
189	// 购买时刻不晚于本次判断时刻、保修尚未到期且故障未被除外。无需再次提交
190	// 或替换请求，再查询原请求时资格按登记资料正常判断；沿用刚才失败的承诺
191	// 编号和预留内容、到期时刻仍晚于本次时刻时成功预留 3 件。实物仍 10 件、
192	// 有效占用变为 7、可承诺变为 3，另一张请求的 4 件保持原值。成功历史的
193	// 资格依据对应补登条款，库存依据是新增占用前的 10/4/6。此前的产品缺失
194	// 记录仍在前面且依据仍为空，不被回填或覆盖，两条记录序号各自递增。
195	func TestRequestBeforeProduct_RegisterEligibleThenRetrySucceeds(t *testing.T) {
196		s, clk := lpBaseScenario(t)
197	
198		// 产品缺失期间先失败一次，留下 seq=1 的缺失记录。
199		if _, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.firstExp, clk.firstAt); !errors.Is(err, ErrNotFound) {
200			t.Fatalf("reserve while product missing: got %v, want ErrNotFound", err)
201		}
202		assertStock10x6(t, s, clk.firstAt)
203	
204		// 补登产品：购买时刻不晚于本次判断时刻、保修 30 天（在 secondAt 尚未到期）、
205		// 除外清单不含 NOISE。
206		if err := s.RegisterProduct(lpProductID, clk.purchase, 30, []string{"BROKEN_SEAL"}); err != nil {
207			t.Fatalf("register product after request: %v", err)
208		}
209	
210		// 无需再次提交或替换请求：原请求的资格按补登资料正常判断。
211		e, err := s.Evaluate(lpReqID, clk.secondAt)
212		if err != nil {
213			t.Fatalf("evaluate after registration: %v", err)
214		}
215		if !e.Eligible || e.Excluded || len(e.Reasons) != 0 {
216			t.Fatalf("expected eligible under late-registered terms, got %+v", e)
217		}
218		if e.ProductID != lpProductID || e.FaultCode != lpFaultCode {
219			t.Fatalf("eligibility identity = %q/%q, want %q/%q", e.ProductID, e.FaultCode, lpProductID, lpFaultCode)
220		}
221		if !e.PurchaseTime.Equal(clk.purchase) || e.WarrantyDays != 30 || !e.WarrantyExpiry.Equal(clk.deadline) {
222			t.Fatalf("eligibility basis = (%v, %d, %v), want late-registered terms (%v, 30, %v)",
223				e.PurchaseTime, e.WarrantyDays, e.WarrantyExpiry, clk.purchase, clk.deadline)
224		}
225		// 按请求查看同样按补登条款判断，并仍无关联承诺。
226		view, err := s.RequestView(lpReqID, clk.secondAt)
227		if err != nil {
228			t.Fatalf("request view after registration: %v", err)
229		}
230		if !view.Eligibility.Eligible || len(view.Commitments) != 0 {
231			t.Fatalf("view after registration: eligible=%v commitments=%+v", view.Eligibility.Eligible, view.Commitments)
232		}
233	
234		// 沿用刚才失败的承诺编号和预留内容再次申请，到期时刻仍晚于本次时刻：成功。
235		c, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.secondExp, clk.secondAt)
236		if err != nil {
237			t.Fatalf("retry reserve after registration: %v", err)
238		}
239		if c.ID != lpCommitID || c.RequestID != lpReqID || c.PartID != lpPartID ||
240			c.Quantity != 3 || c.Used != 0 || c.Canceled || c.Expired {
241			t.Fatalf("bad commitment: %+v", c)
242		}
243		if !c.Expiry.Equal(clk.secondExp) {
244			t.Fatalf("commitment expiry = %v, want %v", c.Expiry, clk.secondExp)
245		}
246	
247		// 实物仍 10 件，有效占用变为 7（4+3），可承诺变为 3。
248		st, err := s.PartStatus(lpPartID, clk.secondAt)
249		if err != nil {
250			t.Fatalf("part status: %v", err)
251		}
252		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 7 || st.Committable != 3 {
253			t.Fatalf("stock after success = phys %d / occupied %d / committable %d, want 10/7/3",
254				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
255		}
256		// 另一张请求的 4 件占用保持原值。
257		other, err := s.Commitment(lpOtherCommit)
258		if err != nil {
259			t.Fatalf("other commitment: %v", err)
260		}
261		if other.Quantity != 4 || other.Used != 0 || other.Canceled || other.Expired {
262			t.Fatalf("other commitment altered: %+v", other)
263		}
264		// 明细恰为两笔有效承诺，数量分别为 4 和 3。
265		if len(st.Details) != 2 {
266			t.Fatalf("part details = %+v, want 2 active commitments", st.Details)
267		}
268		byID := map[string]CommitmentDetail{}
269		for _, d := range st.Details {
270			byID[d.CommitmentID] = d
271			if d.Status != CommitmentActive {
272				t.Fatalf("commitment %q status = %q, want active", d.CommitmentID, d.Status)
273			}
274		}
275		if byID[lpOtherCommit].OriginalQuantity != 4 || byID[lpCommitID].OriginalQuantity != 3 {
276			t.Fatalf("detail quantities altered: other=%d retry=%d",
277				byID[lpOtherCommit].OriginalQuantity, byID[lpCommitID].OriginalQuantity)
278		}
279	
280		// 历史两条：此前的产品缺失记录仍在前面（seq=1），依据仍为空；
281		// 成功记录在后（seq=2），不覆盖也不回填前一条。
282		h, err := s.RequestHistory(lpReqID)
283		if err != nil {
284			t.Fatalf("history: %v", err)
285		}
286		if len(h) != 2 {
287			t.Fatalf("history len = %d, want 2", len(h))
288		}
289		assertMissingProductFailureRecord(t, h[0], 1, clk)
290		ok := h[1]
291		if ok.Seq != 2 || !ok.Success || ok.Error != "" {
292			t.Fatalf("second record should be success with seq 2: %+v", ok)
293		}
294		if ok.CommitID != lpCommitID || ok.PartID != lpPartID || ok.Quantity != 3 ||
295			!ok.Expiry.Equal(clk.secondExp) || !ok.Now.Equal(clk.secondAt) {
296			t.Fatalf("success submission content: %+v", ok)
297		}
298		// 成功历史的资格依据对应补登的产品条款。
299		if ok.Eligibility == nil {
300			t.Fatal("success record missing eligibility basis")
301		}
302		if !ok.Eligibility.Eligible || ok.Eligibility.Excluded || len(ok.Eligibility.Reasons) != 0 ||
303			ok.Eligibility.ProductID != lpProductID || ok.Eligibility.FaultCode != lpFaultCode ||
304			!ok.Eligibility.PurchaseTime.Equal(clk.purchase) || ok.Eligibility.WarrantyDays != 30 ||
305			!ok.Eligibility.WarrantyExpiry.Equal(clk.deadline) {
306			t.Fatalf("success eligibility basis should match late-registered terms: %+v", ok.Eligibility)
307		}
308		// 库存依据是新增占用前的 10 件实物、4 件占用和 6 件可承诺。
309		if ok.StockBasis == nil {
310			t.Fatal("success record missing stock basis")
311		}
312		if ok.StockBasis.PhysicalRemaining != 10 || ok.StockBasis.ActiveOccupied != 4 ||
313			ok.StockBasis.Committable != 6 {
314			t.Fatalf("success stock basis = %+v, want pre-addition 10/4/6", ok.StockBasis)
315		}
316	
317		// 补登与成功预留都不改变原请求的产品编号与故障代码。
318		req, err := s.Request(lpReqID)
319		if err != nil {
320			t.Fatalf("request lookup: %v", err)
321		}
322		if req.ProductID != lpProductID || req.FaultCode != lpFaultCode {
323			t.Fatalf("request identity altered: %+v", req)
324		}
325	}
326	
327	// TestRequestBeforeProduct_RegisterExcludingTermsRejects 另一种补登条件：
328	// 登记的条款已将原请求的故障代码列为除外。资格明确显示除外原因，预留
329	// 返回 ErrIneligible；不新增占用，失败历史保存本次已取得的资格与库存
330	// 依据；原请求的产品编号、故障代码及此前缺失资料的记录均保留。
331	func TestRequestBeforeProduct_RegisterExcludingTermsRejects(t *testing.T) {
332		s, clk := lpBaseScenario(t)
333	
334		// 产品缺失期间先失败一次，留下 seq=1 的缺失记录。
335		if _, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.firstExp, clk.firstAt); !errors.Is(err, ErrNotFound) {
336			t.Fatalf("reserve while product missing: got %v, want ErrNotFound", err)
337		}
338	
339		// 补登条款把原请求的故障代码 NOISE 列为除外（保修期本身仍有效）。
340		if err := s.RegisterProduct(lpProductID, clk.purchase, 30, []string{lpFaultCode}); err != nil {
341			t.Fatalf("register excluding product: %v", err)
342		}
343	
344		// 资格明确显示除外原因：不合格、命中除外、拒绝原因恰为故障除外一项。
345		e, err := s.Evaluate(lpReqID, clk.secondAt)
346		if err != nil {
347			t.Fatalf("evaluate after excluding registration: %v", err)
348		}
349		if e.Eligible || !e.Excluded {
350			t.Fatalf("expected excluded, got %+v", e)
351		}
352		if len(e.Reasons) != 1 || e.Reasons[0] != ReasonFaultExcluded {
353			t.Fatalf("reasons = %v, want exactly [fault_code_excluded]", e.Reasons)
354		}
355		if !e.PurchaseTime.Equal(clk.purchase) || e.WarrantyDays != 30 || !e.WarrantyExpiry.Equal(clk.deadline) {
356			t.Fatalf("eligibility basis = (%v, %d, %v), want late-registered terms",
357				e.PurchaseTime, e.WarrantyDays, e.WarrantyExpiry)
358		}
359		view, err := s.RequestView(lpReqID, clk.secondAt)
360		if err != nil {
361			t.Fatalf("request view: %v", err)
362		}
363		if view.Eligibility.Eligible || !view.Eligibility.Excluded ||
364			len(view.Eligibility.Reasons) != 1 || view.Eligibility.Reasons[0] != ReasonFaultExcluded {
365			t.Fatalf("view eligibility = %+v, want fault_code_excluded", view.Eligibility)
366		}
367	
368		// 沿用同一编号与预留内容再次申请：返回 ErrIneligible。
369		if _, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.secondExp, clk.secondAt); !errors.Is(err, ErrIneligible) {
370			t.Fatalf("reserve under excluding terms: got %v, want ErrIneligible", err)
371		}
372	
373		// 不新增占用：实物 10、有效占用 4、可承诺 6，且不生成承诺。
374		assertStock10x6(t, s, clk.secondAt)
375		if _, err := s.Commitment(lpCommitID); !errors.Is(err, ErrNotFound) {
376			t.Fatalf("ineligible retry created a commitment: got %v", err)
377		}
378		view, err = s.RequestView(lpReqID, clk.secondAt)
379		if err != nil {
380			t.Fatalf("request view after ineligible retry: %v", err)
381		}
382		if len(view.Commitments) != 0 {
383			t.Fatalf("ineligible retry gained commitments: %+v", view.Commitments)
384		}
385	
386		// 历史两条：此前缺失记录保留在前且依据为空；本次失败记录保存已取得的
387		// 资格与库存依据（备件存在，库存依据非空）。
388		h, err := s.RequestHistory(lpReqID)
389		if err != nil {
390			t.Fatalf("history: %v", err)
391		}
392		if len(h) != 2 {
393			t.Fatalf("history len = %d, want 2", len(h))
394		}
395		assertMissingProductFailureRecord(t, h[0], 1, clk)
396		excl := h[1]
397		if excl.Seq != 2 || excl.Success || excl.Error != HistoryErrorIneligible {
398			t.Fatalf("second record should be ineligible failure with seq 2: %+v", excl)
399		}
400		if excl.CommitID != lpCommitID || excl.PartID != lpPartID || excl.Quantity != 3 ||
401			!excl.Expiry.Equal(clk.secondExp) || !excl.Now.Equal(clk.secondAt) {
402			t.Fatalf("ineligible submission content: %+v", excl)
403		}
404		if excl.Eligibility == nil {
405			t.Fatal("ineligible record should preserve the obtained eligibility")
406		}
407		if excl.Eligibility.Eligible || !excl.Eligibility.Excluded ||
408			len(excl.Eligibility.Reasons) != 1 || excl.Eligibility.Reasons[0] != ReasonFaultExcluded ||
409			excl.Eligibility.ProductID != lpProductID || excl.Eligibility.FaultCode != lpFaultCode ||
410			!excl.Eligibility.PurchaseTime.Equal(clk.purchase) || excl.Eligibility.WarrantyDays != 30 ||
411			!excl.Eligibility.WarrantyExpiry.Equal(clk.deadline) {
412			t.Fatalf("ineligible record eligibility should match late-registered excluding terms: %+v", excl.Eligibility)
413		}
414		if excl.StockBasis == nil {
415			t.Fatal("ineligible record should preserve the obtained stock basis")
416		}
417		if excl.StockBasis.PhysicalRemaining != 10 || excl.StockBasis.ActiveOccupied != 4 ||
418			excl.StockBasis.Committable != 6 {
419			t.Fatalf("ineligible record stock basis = %+v, want 10/4/6", excl.StockBasis)
420		}
421	
422		// 原请求的产品编号与故障代码均保留。
423		req, err := s.Request(lpReqID)
424		if err != nil {
425			t.Fatalf("request lookup: %v", err)
426		}
427		if req.ProductID != lpProductID || req.FaultCode != lpFaultCode {
428			t.Fatalf("request identity altered: %+v", req)
429		}
430	}
431

